function ex_vstab_ito()
%EX_VSTAB_ITO  Ito versus Stratonovich stochastic integrals of Brownian paths.
%   Vector-stability appendix (Appendix E), Wiener/diffusion section
%   (Figure fig:vstab:ito).
%
%   MODEL.  Five independent standard Brownian paths W(t) on [0,T] are
%   generated by the Euler increment W(t+dt) = W(t) + sqrt(dt) N(0,1), with
%   W(0) = 0.  For each path the two stochastic integrals of W against dW
%   are formed in closed form:
%       Ito         : int_0^t W dW        = W(t)^2/2 - t/2   (eq:vstab:itoex)
%       Stratonovich: int_0^t W o dW      = W(t)^2/2         (eq:vstab:stratoex)
%   The -t/2 correction is the whole point: the Ito integral is a
%   martingale (mean zero), the Stratonovich integral obeys ordinary
%   calculus.
%
%   PARAMETERS (faithful to the legacy code).  T = 1, dt = 1e-4, N = 5 paths.
%   Seeded rng(1,'twister') for reproducibility.
%
%   OUTPUT.  One vertically stacked combined vector PDF,
%   figures/vecapp_ItoStrato.pdf: (a) the five Ito integrals, (b) the five
%   Stratonovich integrals.  Figures only, no data macros.

here   = fileparts(mfilename('fullpath'));
root   = fullfile(here,'..');
% requires mvst_setup (library and solvers on the path)
mvst_latexdefaults(); gc = mvst_gemcolors();
figdir = mvst_figdir();

% ------------------------------------------------------------- parameters
T  = 1;  dt = 1e-4;  N = 5;
t  = 0:dt:T;  L = numel(t);
rng(1,'twister');                        % fixed, documented seed

% ----------------------------------------------------- Brownian paths
W = zeros(N, L);
for i = 1:L-1
    W(:,i+1) = W(:,i) + sqrt(dt)*randn(N,1);
end

% ----------------------------------------------------- stochastic integrals
Ito    = W.^2/2 - t/2;                    % martingale (mean zero)
Strato = W.^2/2;                          % ordinary calculus

% --------------------------------------------------------------- combined PDF
fig = figure('Color','w','Units','centimeters','Position',[2 2 14 15]);
tl  = tiledlayout(fig,2,1,'TileSpacing','compact','Padding','compact');

ax = nexttile(tl); hold(ax,'on'); grid(ax,'on'); box(ax,'on');
set(ax,'ColorOrder',gc.order); set(ax,'LineStyleOrder','-');
plot(ax, t, Ito, 'LineWidth', 1.1);
xlabel(ax,'$t$','Interpreter','latex');
ylabel(ax,'$\int_0^t W\,\mathrm{d}W$','Interpreter','latex');
title(ax,'(a) It\^o integral $\;W(t)^2/2-t/2$','Interpreter','latex');
set(ax,'FontSize',13);

ax = nexttile(tl); hold(ax,'on'); grid(ax,'on'); box(ax,'on');
set(ax,'ColorOrder',gc.order); set(ax,'LineStyleOrder','-');
plot(ax, t, Strato, 'LineWidth', 1.1);
xlabel(ax,'$t$','Interpreter','latex');
ylabel(ax,'$\int_0^t W\circ\mathrm{d}W$','Interpreter','latex');
title(ax,'(b) Stratonovich integral $\;W(t)^2/2$','Interpreter','latex');
set(ax,'FontSize',13);

mvst_savepdf(fig, fullfile(figdir,'vecapp_ItoStrato.pdf'));
fprintf('  wrote vecapp_ItoStrato.pdf (T=%g, dt=%g, N=%d paths)\n', T, dt, N);
end
